ScheduleTable_theme:
QTableWidget {
    border-style: solid;
    border-width: 1px;
    border-color: none grey none none;
}
QHeaderView::section {
    color: rgb(0, 0, 0);
    background-color: rgb(218, 165, 32);
    font-weight: bold;
}

QDate_edit:
QDateEdit {
    color: rgb(230, 230, 230); 

    border: 2px solid rgb(184, 134, 11);
}

QCalendarWidget QTableView {
    selection-background-color: rgb(184, 134, 11);  /* Цвет выделения */
}

QCalendarWidget QWidget#qt_calendar_navigationbar { 
    background-color: rgb(0, 0, 0); 
    color: white;
}

QCalendarWidget QTableView QHeaderView::section {
    background-color: rgb(255, 255, 255);  /* Цвет строки дней недели */
    color: rgb(255, 255, 255);    /* Цвет текста */
    font-weight: bold;
}
